function largestRectangle(grid: string[][]): number {
  const R = grid.length, C = grid[0].length;
  let best = 0;
  for (let i = 0; i < R; i++) {
    for (let j = 0; j < C; j++) {
      let width = Infinity;
      for (let k = i; k < R && grid[k][j] === "1"; k++) {
        let w = 0;
        while (j + w < C && w < width && grid[k][j + w] === "1") w++;
        width = w;
        best = Math.max(best, width * (k - i + 1));
      }
    }
  }
  return best;
}

