function largestRectangle(grid: string[][]): number {
  const C = grid[0].length;
  const heights = new Array(C + 1).fill(0); // heights[C] stays 0 as a sentinel
  let best = 0;
  for (const row of grid) {
    for (let j = 0; j < C; j++) heights[j] = row[j] === "1" ? heights[j] + 1 : 0;
    const stack: number[] = [];
    for (let j = 0; j <= C; j++) {
      while (stack.length && heights[stack[stack.length - 1]] > heights[j]) {
        const h = heights[stack.pop()!];
        const left = stack.length ? stack[stack.length - 1] : -1;
        best = Math.max(best, h * (j - left - 1));
      }
      stack.push(j);
    }
  }
  return best;
}

